import type { StepFlowEntry, StepResult } from '../..';
import { RequestContext } from '../../../di';
import { getErrorFromUnknown } from '../../../error';
import type { PubSub } from '../../../events';
import { isFrameworkCondition } from '../../framework-condition';
import type { RunStorage } from '../../run-storage';
import { getEntryId, getEntryWorkflow } from '../../step-entry';
import { resolveForeachConcurrency } from '../../utils';
import {
  isNonRedeliverable,
  markNonRedeliverable,
  resolveCurrentState,
  RunFailure,
  withoutAuthToken,
} from '../helpers';
import type { StepExecutor } from '../step-executor';
import { createPendingMarker } from '../types';
import { currentStorageVersion } from './storage-scope';
import type { ProcessorArgs } from '.';

const FOREACH_QUEUED = '__mastra_foreach_queued__';

export function isQueuedForeachIteration(value: unknown): value is { [FOREACH_QUEUED]: true; nestedRunId?: string } {
  return Boolean(value && typeof value === 'object' && FOREACH_QUEUED in value);
}

export async function evaluateLoopCondition(
  args: Omit<ProcessorArgs, 'workflow'>,
  step: Extract<StepFlowEntry, { type: 'loop' }>,
  stepExecutor: StepExecutor,
  stepResult: StepResult<any, any, any, any>,
) {
  const evaluation = stepExecutor.evaluateCondition({
    workflowId: args.workflowId,
    condition: step.condition,
    runId: args.runId,
    // The body's latest result only arrives as stepResult, so expose it to the condition's
    // getStepResult(body) the way the default engine does (handlers/control-flow.ts).
    stepResults: { ...args.stepResults, [getEntryId(step.step)]: stepResult },
    state: resolveCurrentState({ stepResult, stepResults: args.stepResults, state: args.state }),
    requestContext: new RequestContext(Object.entries(args.requestContext ?? {}) as any),
    actor: args.actor,
    inputData: stepResult.status === 'success' ? stepResult.output : undefined,
    resumeData: args.resumeData,
    abortController: new AbortController(),
    retryCount: args.retryCount ?? 0,
    iterationCount: (args.stepResults[getEntryId(step.step)]?.metadata?.iterationCount ?? 0) + 1,
  });
  return evaluation.catch(error => {
    if (isFrameworkCondition(step.condition)) throw error;
    // Redelivery would run the user condition again, and a step body before it.
    throw userCallbackError(error);
  });
}

/** A user callback's error, marked so its delivery is not retried. */
function userCallbackError(error: unknown): Error {
  // A frozen error cannot take the marker, so wrap it.
  const markable =
    typeof error === 'object' && error !== null && !Object.isExtensible(error)
      ? new Error(String((error as { message?: unknown }).message ?? error), { cause: error })
      : error;
  return markNonRedeliverable(getErrorFromUnknown(markable, { serializeStack: false }));
}

/** The loop step's result when its condition throws. */
export function failedLoopStep(result: StepResult<any, any, any, any>, error: Error): StepResult<any, any, any, any> {
  return {
    status: 'failed',
    error,
    payload: result.payload,
    startedAt: result.startedAt ?? Date.now(),
    endedAt: Date.now(),
    nonRetryable: true,
    metadata: result.metadata,
  };
}

export async function processWorkflowLoop(
  {
    workflowId,
    prevResult,
    runId,
    executionPath,
    stepResults,
    activeStepsPath,
    resumeSteps,
    resumeData,
    parentWorkflow,
    requestContext,
    actor,
    retryCount = 0,
    perStep,
    state,
    outputOptions,
  }: ProcessorArgs,
  {
    pubsub,
    runStorage,
    stepExecutor,
    step,
    stepResult,
    savedCondition,
    replayedIterationCount,
  }: {
    pubsub: PubSub;
    runStorage: RunStorage;
    stepExecutor: StepExecutor;
    step: Extract<StepFlowEntry, { type: 'loop' }>;
    stepResult: StepResult<any, any, any, any>;
    savedCondition?: boolean;
    /**
     * The count already stored for this completion by an earlier delivery's `loopAgain`. A replay
     * must report the same count instead of advancing it a second time.
     */
    replayedIterationCount?: number;
  },
) {
  // Get current state from stepResult, stepResults or passed state
  const currentState = resolveCurrentState({ stepResult, stepResults, state });

  const prevIterationCount = stepResults[getEntryId(step.step)]?.metadata?.iterationCount ?? 0;
  const iterationCount = replayedIterationCount ?? prevIterationCount + 1;
  const loopCondition =
    savedCondition ??
    (await evaluateLoopCondition(
      {
        workflowId,
        runId,
        executionPath,
        stepResults,
        activeStepsPath,
        resumeSteps,
        resumeData,
        requestContext,
        actor,
        retryCount,
        state: currentState,
        prevResult,
      },
      step,
      stepExecutor,
      stepResult,
    ));

  const countedBody = {
    ...stepResults[getEntryId(step.step)],
    metadata: { ...stepResults[getEntryId(step.step)]?.metadata, ...stepResult.metadata, iterationCount },
  };
  const loopAgain = async () => {
    // On storage v2 the body's dispatch loads step results from the stored run, not this message.
    // (Before the body's first result is stored this is only the count, as on the v1 message.)
    if (currentStorageVersion() === 2) {
      await runStorage.writeStepResult({
        stepId: getEntryId(step.step),
        // Unguarded stores have no committed body result here; record the next iteration as
        // started with its input, so a restart re-runs it instead of a body with no input.
        result:
          savedCondition === undefined
            ? {
                status: 'running',
                payload: stepResult.status === 'success' ? stepResult.output : undefined,
                startedAt: Date.now(),
                metadata: countedBody.metadata,
              }
            : (countedBody as StepResult<any, any, any, any>),
        requestContext: withoutAuthToken(requestContext),
        // The body's state as of this iteration, next to its next input: a restart then resumes
        // from the state its input belongs to instead of the previous iteration's.
        state: currentState,
      });
    }
    await pubsub.publish('workflows', { type: 'workflow.step.run', runId, data: loopAgainData });
  };

  // When the loop body runs again, it's a fresh iteration — not a resume — so drop any
  // resume metadata. Otherwise the body would keep receiving the same resumeData on every
  // iteration (and e.g. never re-suspend).
  const loopAgainData = {
    parentWorkflow,
    workflowId,
    runId,
    executionPath,
    resumeSteps: [] as string[],
    // Carry the iteration count forward on the loop body's stepResults entry. The
    // loop-again path does not merge the body result back into stepResults[bodyStepId]
    // (only prevResult carries it), and the evented step executor never writes
    // iterationCount, so without this the next processWorkflowLoop re-reads 0 and the
    // condition is always evaluated with iterationCount === 1 (an infinite loop when
    // termination depends on the count). Mirrors the default engine, which stamps
    // metadata.iterationCount onto the step result. See handlers/step.ts.
    stepResults: { ...stepResults, [getEntryId(step.step)]: countedBody },
    prevResult: stepResult,
    resumeData: undefined,
    activeStepsPath,
    requestContext,
    actor,
    // Each iteration gets the body's full retry budget, as on the default engine.
    retryCount: 0,
    perStep,
    state: currentState,
    outputOptions,
  };
  const loopEndData = {
    parentWorkflow,
    workflowId,
    runId,
    executionPath,
    resumeSteps,
    stepResults,
    prevResult: stepResult,
    resumeData,
    activeStepsPath,
    requestContext,
    actor,
    perStep,
    state: currentState,
    outputOptions,
  };

  if (step.loopType === 'dountil') {
    if (loopCondition) {
      await pubsub.publish('workflows', { type: 'workflow.step.end', runId, data: loopEndData });
    } else {
      await loopAgain();
    }
  } else if (loopCondition) {
    await loopAgain();
  } else {
    await pubsub.publish('workflows', { type: 'workflow.step.end', runId, data: loopEndData });
  }
}

export async function processWorkflowForEach(
  args: ProcessorArgs,
  deps: {
    pubsub: PubSub;
    runStorage: RunStorage;
    step: Extract<StepFlowEntry, { type: 'foreach' }>;
  },
) {
  try {
    return await advanceForEach(args, deps);
  } catch (error) {
    if (!isNonRedeliverable(error)) throw error;
    // The concurrency function threw. Fail the run at the foreach step, so the failed step
    // is recorded and streamed.
    const stepId = getEntryId(deps.step.step);
    const failed: StepResult<any, any, any, any> = {
      status: 'failed',
      error: error as Error,
      payload: (args.prevResult as any)?.output,
      startedAt: Date.now(),
      endedAt: Date.now(),
      nonRetryable: true,
    };
    const { workflow: _workflow, ...run } = args;
    const failRun = {
      ...run,
      executionPath: [args.executionPath[0]!],
      stepResults: { ...args.stepResults, [stepId]: failed },
      prevResult: failed,
      state: resolveCurrentState({ stepResults: args.stepResults, state: args.state }),
    };
    try {
      await deps.pubsub.publish('workflows', { type: 'workflow.fail', runId: args.runId, data: failRun });
    } catch {
      // A plain throw here would be redelivered and call the concurrency function again.
      throw markNonRedeliverable(new RunFailure(error as Error, failRun));
    }
  }
}

async function advanceForEach(
  {
    workflowId,
    prevResult,
    runId,
    executionPath,
    stepResults,
    activeStepsPath,
    resumeSteps,
    timeTravel,
    restart,
    resumeData,
    parentWorkflow,
    requestContext,
    actor,
    perStep,
    state,
    outputOptions,
    forEachIndex,
  }: ProcessorArgs,
  {
    pubsub,
    runStorage,
    step,
  }: {
    pubsub: PubSub;
    runStorage: RunStorage;
    step: Extract<StepFlowEntry, { type: 'foreach' }>;
  },
) {
  // Restart checkpoints may point at an iteration, but the coordinator advances the workflow path.
  if (restart) executionPath = [executionPath[0]!];

  // Get current state from stepResults or passed state
  const currentState = resolveCurrentState({ stepResults, state });
  const resolveConcurrency = () => {
    try {
      return resolveForeachConcurrency(step.opts, {
        inputData: (prevResult as any)?.output,
        getInitData: () => (stepResults as any)?.input,
      });
    } catch (error) {
      throw userCallbackError(error);
    }
  };
  const currentResult: Extract<StepResult<any, any, any, any>, { status: 'success' }> = stepResults[
    getEntryId(step.step)
  ] as any;

  const idx = currentResult?.output?.length ?? 0;
  const targetLen = (prevResult as any)?.output?.length ?? 0;

  const publishSuspendedState = async (suspendedForEachIndex: number | undefined) => {
    const collectedResumeLabels: Record<string, { stepId: string; foreachIndex?: number }> = {};
    let firstSuspendedIterationPayload: Record<string, unknown> | undefined;
    for (const iterResult of currentResult.output) {
      if (iterResult?.status === 'suspended') {
        if (iterResult.suspendPayload?.__workflow_meta?.resumeLabels) {
          Object.assign(collectedResumeLabels, iterResult.suspendPayload.__workflow_meta.resumeLabels);
        }
        if (firstSuspendedIterationPayload === undefined) {
          firstSuspendedIterationPayload = iterResult.suspendPayload;
        }
      }
    }

    const suspendMeta: {
      foreachIndex?: number;
      resumeLabels?: Record<string, { stepId: string; foreachIndex?: number }>;
    } = {
      foreachIndex: suspendedForEachIndex,
    };
    if (Object.keys(collectedResumeLabels).length > 0) {
      suspendMeta.resumeLabels = collectedResumeLabels;
    }

    // Concurrent per-item writes can drop each other's entries from the stored foreachOutput, so
    // each suspended item's record comes from the merged output, where every item has its own slot.
    const foreachOutput = [...(currentResult?.suspendPayload?.__workflow_meta?.foreachOutput ?? [])];
    currentResult.output.forEach((iterResult: any, i: number) => {
      if (iterResult?.status !== 'suspended') return;
      const { payload: _payload, ...iterationRecord } = iterResult;
      foreachOutput[i] = iterationRecord;
    });

    const aggregatedSuspendPayload = {
      ...firstSuspendedIterationPayload,
      __workflow_meta: {
        ...currentResult?.suspendPayload?.__workflow_meta,
        ...(firstSuspendedIterationPayload?.__workflow_meta as Record<string, unknown> | undefined),
        ...suspendMeta,
        foreachOutput,
      },
    };

    await pubsub.publish('workflows', {
      type: 'workflow.step.end',
      runId,
      data: {
        parentWorkflow,
        workflowId,
        runId,
        executionPath,
        resumeSteps,
        stepResults: {
          ...stepResults,
          [getEntryId(step.step)]: {
            ...currentResult,
            status: 'suspended',
            suspendedAt: Date.now(),
            suspendPayload: aggregatedSuspendPayload,
          },
        },
        prevResult: {
          status: 'suspended',
          output: currentResult.output,
          suspendPayload: aggregatedSuspendPayload,
          payload: currentResult.payload,
          startedAt: currentResult.startedAt,
          suspendedAt: Date.now(),
        },
        activeStepsPath,
        requestContext,
        actor,
        state: currentState,
        outputOptions,
      },
    });
  };

  // Handle resume with forEachIndex: kick off the targeted iteration resume
  if (forEachIndex !== undefined && resumeSteps?.length > 0 && idx > 0) {
    // Validate forEachIndex is within bounds to fail loudly instead of silently no-op
    const outputArray = currentResult?.output;
    const outputLength = Array.isArray(outputArray) ? outputArray.length : 0;
    if (!Array.isArray(outputArray) || forEachIndex < 0 || forEachIndex >= outputLength) {
      const error = new Error(
        `Invalid forEachIndex ${forEachIndex} for forEach resume: ` +
          `expected index in range [0, ${outputLength - 1}] but output array has length ${outputLength}`,
      );
      await pubsub.publish('workflows', {
        type: 'workflow.fail',
        runId,
        data: {
          parentWorkflow,
          workflowId,
          runId,
          executionPath,
          resumeSteps,
          stepResults,
          prevResult: { status: 'failed', error },
          activeStepsPath,
          requestContext,
          actor,
          state: currentState,
          outputOptions,
        },
      });
      return;
    }

    // Check if the target iteration is suspended
    const iterationResult = currentResult?.output?.[forEachIndex];
    if (iterationResult?.status === 'suspended' || iterationResult === null) {
      // Only pass resumeData to the targeted iteration
      const isNestedWorkflow = getEntryWorkflow(step.step) !== null;
      const targetArray = (prevResult as any)?.output;
      const iterationPrevResult =
        isNestedWorkflow && prevResult.status === 'success' && Array.isArray(targetArray)
          ? { status: 'success' as const, output: targetArray[forEachIndex] }
          : prevResult;

      await pubsub.publish('workflows', {
        type: 'workflow.step.run',
        runId,
        data: {
          parentWorkflow,
          workflowId,
          runId,
          executionPath: [executionPath[0]!, forEachIndex],
          resumeSteps,
          timeTravel,
          restart,
          stepResults,
          prevResult: iterationPrevResult,
          resumeData,
          activeStepsPath,
          requestContext,
          actor,
          perStep,
          state: currentState,
          outputOptions,
        },
      });
      return;
    }

    // If forEachIndex was provided but the iteration is already complete,
    // check if there are still pending (null or suspended) iterations.
    // If so, re-suspend the workflow to wait for those to be resumed.
    const pendingIterations = currentResult.output.filter((r: any) => r === null || r?.status === 'suspended');
    if (pendingIterations.length > 0) {
      // Re-suspend the workflow - there are still pending iterations.
      await publishSuspendedState(forEachIndex);
      return;
    }

    // forEachIndex was provided but the target iteration is already complete,
    // and there are no pending iterations. The workflow step.end handler will
    // advance the workflow. This is expected behavior for completed forEach loops.
    return;
  }

  // Handle bulk resume: when resumeData is provided but no forEachIndex,
  // resume suspended iterations up to the concurrency limit
  if (resumeData !== undefined && forEachIndex === undefined && currentResult?.output?.length > 0) {
    const suspendedIndices: number[] = [];
    for (let i = 0; i < currentResult.output.length; i++) {
      const iterResult = currentResult.output[i];
      if (iterResult && typeof iterResult === 'object' && iterResult.status === 'suspended') {
        suspendedIndices.push(i);
      }
    }

    if (suspendedIndices.length > 0) {
      // Limit resumption to concurrency value (like initial execution)
      const concurrency = resolveConcurrency();
      const indicesToResume = suspendedIndices.slice(0, concurrency);

      // Reset suspended iterations to "pending" state before re-running them.
      //
      // Why PendingMarker instead of null?
      // The storage merge logic treats null as "keep existing value" to prevent
      // completed results from being overwritten by concurrent iterations that
      // haven't finished yet. But when resuming, we need to force-reset the
      // suspended result to null so the iteration can run fresh.
      //
      // PendingMarker ({ __mastra_pending__: true }) tells the storage layer
      // "force this to null, don't preserve the existing suspended result."
      // See inmemory.ts updateWorkflowResults for the merge logic.
      const updatedOutput = [...currentResult.output];
      for (const suspIdx of indicesToResume) {
        updatedOutput[suspIdx] = createPendingMarker() as any;
      }

      await runStorage.mergeStepResult({
        stepId: getEntryId(step.step),
        result: {
          ...currentResult,
          output: updatedOutput,
        } as any,
        requestContext: withoutAuthToken(requestContext),
      });

      // Check if inner step is a nested workflow
      const isNestedWorkflow = getEntryWorkflow(step.step) !== null;

      // Resume iterations up to concurrency limit
      // Wrap in try-catch to prevent partial state issues if some publishes fail
      for (const suspIdx of indicesToResume) {
        const targetArray = (prevResult as any)?.output;
        const iterationPrevResult =
          isNestedWorkflow && prevResult.status === 'success' && Array.isArray(targetArray)
            ? { status: 'success' as const, output: targetArray[suspIdx] }
            : prevResult;

        try {
          await pubsub.publish('workflows', {
            type: 'workflow.step.run',
            runId,
            data: {
              parentWorkflow,
              workflowId,
              runId,
              executionPath: [executionPath[0]!, suspIdx],
              resumeSteps,
              timeTravel,
              restart,
              stepResults,
              prevResult: iterationPrevResult,
              resumeData,
              activeStepsPath,
              requestContext,
              actor,
              perStep,
              state: currentState,
              outputOptions,
            },
          });
        } catch {
          // Log error but continue - the iteration will be picked up on next resume
          // State was already updated, so no data loss
        }
      }
      return;
    }
  }
  const stepId = getEntryId(step.step);
  const preservedForeachOutput = currentResult?.suspendPayload?.__workflow_meta?.foreachOutput;

  // Time travel reconstructs the target step without its output. Restore only
  // durable successes and queue every failed or unfinished iteration for replay.
  if (
    timeTravel &&
    (!Array.isArray(currentResult?.output) || currentResult.output.length === 0) &&
    Array.isArray(preservedForeachOutput) &&
    preservedForeachOutput.length > 0
  ) {
    currentResult.output = preservedForeachOutput.map((iterationResult: any) =>
      iterationResult?.status === 'success'
        ? iterationResult.output
        : ({ [FOREACH_QUEUED]: true } as { [FOREACH_QUEUED]: true }),
    );
    // Drop failure records from the previous attempt so a replayed iteration that fails
    // again is treated as the first failure and fails the run.
    currentResult.suspendPayload = {
      ...currentResult.suspendPayload,
      __workflow_meta: {
        ...currentResult.suspendPayload.__workflow_meta,
        foreachOutput: preservedForeachOutput.map((iterationResult: any) =>
          iterationResult?.status === 'failed' ? null : iterationResult,
        ),
      },
    };

    await runStorage.mergeStepResult({
      stepId,
      result: currentResult,
      requestContext: withoutAuthToken(requestContext),
    });
    stepResults[stepId] = currentResult;
  }

  if (
    restart &&
    !restart.isForeachRestarted &&
    Array.isArray(currentResult?.output) &&
    currentResult.output.some((result: any) => result === null)
  ) {
    const unfinishedCount = currentResult.output.filter((result: any) => result === null).length;
    currentResult.output = currentResult.output.map((result: any, index: number) => {
      if (result !== null) return result;
      const nestedRunId =
        currentResult.metadata?.foreachNestedRunIds?.[index] ??
        (!currentResult.metadata?.foreachNestedRunIds &&
        unfinishedCount === 1 &&
        restart.activeStepsPath?.[stepId]?.[1] === index
          ? currentResult.metadata?.nestedRunId
          : undefined);
      return { [FOREACH_QUEUED]: true, ...(nestedRunId ? { nestedRunId } : {}) };
    });

    await runStorage.mergeStepResult({
      stepId,
      result: currentResult,
      requestContext: withoutAuthToken(requestContext),
    });
    stepResults[stepId] = currentResult;
  }

  const queuedIndices = Array.isArray(currentResult?.output)
    ? currentResult.output.flatMap((result: any, index: number) => (isQueuedForeachIteration(result) ? [index] : []))
    : [];
  if (queuedIndices.length > 0) {
    const concurrency = resolveConcurrency();
    const runningCount = currentResult.output.filter((result: any) => result === null).length;
    const suspendedIndices = currentResult.output.flatMap((result: any, index: number) =>
      result?.status === 'suspended' ? [index] : [],
    );
    const indicesToRun = queuedIndices.slice(0, Math.max(0, concurrency - runningCount - suspendedIndices.length));
    if (indicesToRun.length === 0 && runningCount === 0 && suspendedIndices.length > 0) {
      await publishSuspendedState(suspendedIndices[0]);
      return;
    }

    if (indicesToRun.length > 0) {
      const updatedOutput = [...currentResult.output];
      for (const index of indicesToRun) {
        updatedOutput[index] = createPendingMarker() as any;
      }
      await runStorage.mergeStepResult({
        stepId,
        result: { ...currentResult, output: updatedOutput } as any,
        requestContext: withoutAuthToken(requestContext),
      });

      const isNestedWorkflow = getEntryWorkflow(step.step) !== null;
      for (const index of indicesToRun) {
        const targetArray = (prevResult as any)?.output;
        const iterationPrevResult =
          isNestedWorkflow && prevResult.status === 'success' && Array.isArray(targetArray)
            ? { status: 'success' as const, output: targetArray[index] }
            : prevResult;
        await pubsub.publish('workflows', {
          type: 'workflow.step.run',
          runId,
          data: {
            parentWorkflow,
            workflowId,
            runId,
            executionPath: [executionPath[0]!, index],
            resumeSteps,
            timeTravel,
            // Only recorded children receive recovery events. Plain steps and slots
            // that never started still execute normally through the leaf runner.
            restart:
              isNestedWorkflow && !timeTravel && currentResult.output[index]?.nestedRunId
                ? {
                    ...restart,
                    activePaths: restart?.activePaths ?? [executionPath[0]!, index],
                    activeStepsPath: { ...restart?.activeStepsPath, [stepId]: [executionPath[0]!, index] },
                    stepResults,
                    isForeachRestarted: true,
                  }
                : undefined,
            stepResults,
            prevResult: iterationPrevResult,
            resumeData,
            activeStepsPath,
            requestContext,
            actor,
            perStep,
            state: currentState,
            outputOptions,
          },
        });
      }
    }
    return;
  }

  const concurrency = idx === 0 ? undefined : resolveConcurrency();
  const runningIterations = currentResult?.output?.filter((result: any) => result === null).length ?? 0;
  const suspendedIndices =
    currentResult?.output?.flatMap((result: any, index: number) => (result?.status === 'suspended' ? [index] : [])) ??
    [];
  const activeIterations = runningIterations + suspendedIndices.length;

  if (
    suspendedIndices.length > 0 &&
    runningIterations === 0 &&
    (idx >= targetLen || (concurrency !== undefined && activeIterations >= concurrency))
  ) {
    await publishSuspendedState(suspendedIndices[0]);
    return;
  }

  if (
    (idx >= targetLen &&
      currentResult?.output?.filter((r: any) => r !== null && r?.status !== 'suspended' && !isQueuedForeachIteration(r))
        ?.length >= targetLen) ||
    (prevResult as any)?.output?.length === 0
  ) {
    // Foreach completed all iterations or the previous result is an empty array - advance to next step
    // If the previous result is an empty array, we need to create a new result with an empty array output, save to stroage and stepResults
    let result = currentResult;
    if ((prevResult as any)?.output?.length === 0) {
      result = {
        status: 'success',
        output: [],
        startedAt: Date.now(),
        endedAt: Date.now(),
        payload: (prevResult as any)?.output,
      };
      await runStorage.mergeStepResult({
        stepId: getEntryId(step.step),
        result,
        requestContext: withoutAuthToken(requestContext),
      });
      stepResults[getEntryId(step.step)] = result as StepResult<any, any, any, any>;
    } else if (currentResult?.status !== 'success') {
      // Iteration step-ends keep the record 'running'; only here has every iteration settled.
      result = {
        ...currentResult,
        status: 'success',
        suspendedAt: undefined,
        startedAt: currentResult.startedAt ?? Date.now(),
        endedAt: Date.now(),
      };
      const merged = await runStorage.mergeStepResult({
        stepId: getEntryId(step.step),
        result,
        requestContext: withoutAuthToken(requestContext),
      });
      stepResults[getEntryId(step.step)] = (merged?.results[getEntryId(step.step)] ?? result) as StepResult<
        any,
        any,
        any,
        any
      >;
      result = stepResults[getEntryId(step.step)] as typeof result;
    }

    await pubsub.publish('workflows', {
      type: 'workflow.step.run',
      runId,
      data: {
        parentWorkflow,
        workflowId,
        runId,
        executionPath: executionPath.slice(0, -1).concat([executionPath[executionPath.length - 1]! + 1]),
        resumeSteps,
        stepResults,
        timeTravel,
        restart,
        prevResult: result,
        resumeData: undefined, // No resumeData when advancing past foreach
        activeStepsPath,
        requestContext,
        actor,
        perStep,
        state: currentState,
        outputOptions,
      },
    });

    return;
  } else if (idx >= targetLen) {
    // wait for the 'null' values to be filled from the concurrent run
    return;
  }

  if (executionPath.length === 1 && idx === 0) {
    // on first iteratation we need to kick off up to the set concurrency
    const concurrency = Math.min(resolveConcurrency(), targetLen);
    const dummyResult = Array.from({ length: concurrency }, () => null);

    await runStorage.mergeStepResult({
      stepId: getEntryId(step.step),
      result: {
        // Iterations are still running; the completion branch above writes success.
        status: 'running',
        output: dummyResult as any,
        startedAt: Date.now(),
        payload: (prevResult as any)?.output,
      } as any,
      requestContext: withoutAuthToken(requestContext),
    });

    // Check if inner step is a nested workflow - only then extract individual items
    // Regular steps use foreachIdx in step executor for item extraction
    const isNestedWorkflow = getEntryWorkflow(step.step) !== null;

    for (let i = 0; i < concurrency; i++) {
      // For nested workflows, extract individual item since they receive prevResult directly
      // For regular steps, step executor handles extraction via foreachIdx
      const targetArray = (prevResult as any)?.output;
      const iterationPrevResult =
        isNestedWorkflow && prevResult.status === 'success' && Array.isArray(targetArray)
          ? { status: 'success' as const, output: targetArray[i] }
          : prevResult;
      await pubsub.publish('workflows', {
        type: 'workflow.step.run',
        runId,
        data: {
          parentWorkflow,
          workflowId,
          runId,
          executionPath: [executionPath[0]!, i],
          resumeSteps,
          stepResults,
          timeTravel,
          prevResult: iterationPrevResult,
          resumeData,
          activeStepsPath,
          requestContext,
          actor,
          perStep,
          state: currentState,
          outputOptions,
        },
      });
    }

    return;
  }

  if (concurrency !== undefined && activeIterations >= concurrency) {
    return;
  }

  (currentResult as any).output.push(null);
  await runStorage.mergeStepResult({
    stepId: getEntryId(step.step),
    result: {
      status: 'running',
      output: (currentResult as any).output,
      startedAt: currentResult?.startedAt ?? Date.now(),
      payload: (prevResult as any)?.output,
    } as any,
    requestContext: withoutAuthToken(requestContext),
  });

  // For nested workflows, extract individual item since they receive prevResult directly
  // For regular steps, step executor handles extraction via foreachIdx
  const isNestedWorkflow = getEntryWorkflow(step.step) !== null;
  const targetArray = (prevResult as any)?.output;
  const iterationPrevResult =
    isNestedWorkflow && prevResult.status === 'success' && Array.isArray(targetArray)
      ? { status: 'success' as const, output: targetArray[idx] }
      : prevResult;

  await pubsub.publish('workflows', {
    type: 'workflow.step.run',
    runId,
    data: {
      parentWorkflow,
      workflowId,
      runId,
      executionPath: [executionPath[0]!, idx],
      resumeSteps,
      timeTravel,
      stepResults,
      prevResult: iterationPrevResult,
      resumeData,
      activeStepsPath,
      requestContext,
      actor,
      perStep,
      state: currentState,
      outputOptions,
    },
  });
}
